import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as r,af as n}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const _=JSON.parse('{"title":"扣子 / Coze 学习地图","description":"扣子、扣子编程、扣子罗盘不是同一张皮。本目录主线是在扣子编程里搭建并发布 Agent。豆包和 Trae 不在这里展开。","frontmatter":{"title":"扣子 / Coze 学习地图","description":"扣子、扣子编程、扣子罗盘不是同一张皮。本目录主线是在扣子编程里搭建并发布 Agent。豆包和 Trae 不在这里展开。","domain":"product","tags":["agent-builder"],"role":"map"},"headers":[],"relativePath":"zh/products/coze/index.md","filePath":"zh/products/coze/index.md","lastUpdated":1787107158000}'),s={name:"zh/products/coze/index.md"};function o(d,t,l,c,p,i){return r(),a("div",null,[...t[0]||(t[0]=[n(`<h1 id="扣子-coze-学习地图" tabindex="-1">扣子 / Coze 学习地图 <a class="header-anchor" href="#扣子-coze-学习地图" aria-label="Permalink to &quot;扣子 / Coze 学习地图&quot;">​</a></h1><blockquote><p><strong>扣子编程</strong>才是本目录的搭建主线。官方定义（<a href="https://docs.coze.cn/guides_welcome" target="_blank" rel="noreferrer">什么是扣子编程</a>）：</p><p>「扣子编程是一个 AI 驱动的应用开发平台……只需清晰描述你的需求，扣子编程就能帮助你打造可用于生产环境的智能体、工作流、技能、移动应用、网页应用或小程序。」</p><p><strong>扣子</strong>本身是另一扇门：官方定义（<a href="https://docs.coze.cn/what_is_coze" target="_blank" rel="noreferrer">什么是扣子</a>）是「面向 Agent 时代的新一代 AI 团队协作平台」。它用来调度 Agent，不是低代码画布。</p></blockquote><h2 id="产品全景" tabindex="-1">产品全景 <a class="header-anchor" href="#产品全景" aria-label="Permalink to &quot;产品全景&quot;">​</a></h2><p>字节跳动有多款 AI 产品。带「扣子 / Coze」的也不是同一个东西。本目录<strong>只写 Agent 搭建</strong>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>字节跳动 AI（本目录只展开扣子家族）</span></span>
<span class="line"><span>├── 扣子（coze.cn）— 人和 Agent 一起干活的工作台</span></span>
<span class="line"><span>│   ├── 扣子 Agent / 云端 Agent / 本地 Agent</span></span>
<span class="line"><span>│   ├── 项目协作、技能商店、云电脑 / 云手机</span></span>
<span class="line"><span>│   └── 对话里的 AI 编程（网页 / App / 小程序，能力是扣子编程的子集）</span></span>
<span class="line"><span>├── 扣子编程（code.coze.cn）— 搭智能体 / 工作流 / 应用  ← 本目录主线</span></span>
<span class="line"><span>│   ├── 低代码：可视化编排智能体、工作流、插件、知识库</span></span>
<span class="line"><span>│   ├── AI 编程：一句话生成全代码智能体 / 工作流 / 网页 / App / 小程序 / 技能</span></span>
<span class="line"><span>│   └── Coze CLI（npm @coze/cli）</span></span>
<span class="line"><span>├── 扣子罗盘 — Prompt / 评测 / Trace</span></span>
<span class="line"><span>├── 开源核</span></span>
<span class="line"><span>│   ├── Coze Studio（私有化搭 Agent）</span></span>
<span class="line"><span>│   └── Coze Loop（罗盘开源核）</span></span>
<span class="line"><span>└── 同厂但不在本目录写正文</span></span>
<span class="line"><span>    ├── 豆包 — 聊天助手（#79）</span></span>
<span class="line"><span>    ├── Trae — 编程 IDE（#80）</span></span>
<span class="line"><span>    └── 火山方舟 — 模型 API（#82）</span></span></code></pre></div><table tabindex="0"><thead><tr><th>产品</th><th>是什么</th><th>入口</th><th>本站去向</th></tr></thead><tbody><tr><td><strong>扣子编程</strong></td><td>在浏览器里搭建、调试、发布智能体和应用</td><td><a href="https://code.coze.cn/" target="_blank" rel="noreferrer">code.coze.cn</a></td><td><a href="./coze.html">教程</a></td></tr><tr><td>扣子</td><td>消费端 AI 团队工作台（网页 / 桌面 / App）</td><td><a href="https://www.coze.cn/" target="_blank" rel="noreferrer">coze.cn</a></td><td>地图一行；操作见<a href="https://docs.coze.cn/what_is_coze" target="_blank" rel="noreferrer">官方开始使用</a></td></tr><tr><td>扣子罗盘</td><td>Prompt 开发、评测、全链路观测</td><td><a href="https://docs.coze.cn/cozeloop_what-is-cozeloop" target="_blank" rel="noreferrer">什么是扣子罗盘</a></td><td>地图一行</td></tr><tr><td>Coze Studio</td><td>扣子编程的开源单机引擎</td><td><a href="https://github.com/coze-dev/coze-studio" target="_blank" rel="noreferrer">github.com/coze-dev/coze-studio</a></td><td>地图一行；商业版不支持私有化</td></tr><tr><td>Coze Loop</td><td>罗盘的开源核</td><td><a href="https://github.com/coze-dev/coze-loop" target="_blank" rel="noreferrer">github.com/coze-dev/coze-loop</a></td><td>地图一行</td></tr><tr><td>Coze.com</td><td>国际站</td><td><a href="https://www.coze.com/" target="_blank" rel="noreferrer">coze.com</a>、<a href="https://docs.coze.com/" target="_blank" rel="noreferrer">docs.coze.com</a></td><td>地图一行；账号和渠道与国内不同</td></tr><tr><td>Coze Pro / 企业版</td><td>火山引擎上的企业套餐入口</td><td><a href="https://www.volcengine.com/product/coze-pro" target="_blank" rel="noreferrer">volcengine.com/product/coze-pro</a></td><td>地图一行；权益见<a href="https://docs.coze.cn/guides_edition" target="_blank" rel="noreferrer">套餐</a></td></tr><tr><td>豆包</td><td>同厂通用聊天</td><td><a href="https://www.doubao.com/" target="_blank" rel="noreferrer">doubao.com</a></td><td><strong>不写教程</strong> → issue #79</td></tr><tr><td>Trae</td><td>同厂编程 IDE</td><td><a href="https://www.trae.cn/" target="_blank" rel="noreferrer">trae.cn</a>、<a href="https://www.trae.ai/" target="_blank" rel="noreferrer">trae.ai</a></td><td><strong>不写教程</strong> → issue #80</td></tr><tr><td>火山方舟</td><td>同厂模型 API</td><td><a href="https://www.volcengine.com/product/ark" target="_blank" rel="noreferrer">volcengine.com/product/ark</a></td><td><strong>不写教程</strong> → issue #82</td></tr><tr><td>飞书 / 微信 / 抖音</td><td>发布渠道，不是扣子产品</td><td><a href="https://docs.coze.cn/guides_publish_overview" target="_blank" rel="noreferrer">发布概览</a></td><td>非本站产品</td></tr></tbody></table><p><strong>容易撞名的几条：</strong></p><ul><li><strong>扣子 ≠ 扣子编程</strong>。前者是工作台，后者是开发平台。对话里快速做网页可以留在扣子；要搭智能体、工作流、完整配置，去扣子编程。</li><li><strong>扣子 ≠ 豆包</strong>。豆包是聊天助手。低代码智能体曾能发到豆包渠道，该入口已于 <strong>2026-07-01</strong> 下线（<a href="https://docs.coze.cn/guides_FAQ" target="_blank" rel="noreferrer">FAQ</a>）。</li><li><strong>扣子编程 ≠ Trae</strong>。Trae 是 IDE。扣子编程是云端搭 Agent / 应用的平台。</li><li><strong>低代码智能体 ≠ 全代码智能体</strong>。低代码走可视化编排；全代码走 AI 编程对话。</li><li><strong>云端「Claude Code / Codex CLI」≠ 官方 Claude Code / Codex</strong>。那是框架跑在扣子云电脑，模型由扣子提供，不能登录 Anthropic / OpenAI 账号（<a href="https://docs.coze.cn/cozespace_coze_app_faq" target="_blank" rel="noreferrer">消费端 FAQ</a>）。</li><li><strong>Coze Studio ≠ 扣子编程</strong>。Studio 是开源单机核；扣子编程是云端商业版，官方写明暂不支持私有化。</li><li>旧文案里的 <strong>Bot</strong> 就是现在的低代码智能体。</li></ul><h3 id="快速决策-我该进哪扇门" tabindex="-1">快速决策：我该进哪扇门？ <a class="header-anchor" href="#快速决策-我该进哪扇门" aria-label="Permalink to &quot;快速决策：我该进哪扇门？&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我要做什么？</span></span>
<span class="line"><span>├── 零代码搭一个对话智能体，再发到飞书 / 微信 / API</span></span>
<span class="line"><span>│   └── → 扣子编程 · 低代码智能体（先读教程）</span></span>
<span class="line"><span>├── 流程固定：报告、批处理、多步工具调用</span></span>
<span class="line"><span>│   └── → 扣子编程 · 低代码工作流（Cookbook）</span></span>
<span class="line"><span>├── 一句话生成全代码智能体 / 网页 / App / 小程序</span></span>
<span class="line"><span>│   └── → 扣子编程 · AI 编程（Cookbook）</span></span>
<span class="line"><span>├── 在终端或 Claude Code / Trae 里让 Agent 操作扣子</span></span>
<span class="line"><span>│   └── → Coze CLI（Cookbook / Cheatsheet）</span></span>
<span class="line"><span>├── 和多个 Agent 一起办公、做 PPT / 视频、授权本机文件</span></span>
<span class="line"><span>│   └── → 扣子（coze.cn），本目录不展开逐步教程</span></span>
<span class="line"><span>├── 评 Prompt、跑实验、看 Trace</span></span>
<span class="line"><span>│   └── → 扣子罗盘</span></span>
<span class="line"><span>├── 数据必须留在自己的机器</span></span>
<span class="line"><span>│   └── → Coze Studio 开源版（扣子编程本身不能私有化）</span></span>
<span class="line"><span>├── 只是聊天 / 写文案</span></span>
<span class="line"><span>│   └── → 豆包（#79），不是扣子</span></span>
<span class="line"><span>└── 要在仓库里写代码的 IDE</span></span>
<span class="line"><span>    └── → Trae（#80），或本站 Claude Code / Cursor / Grok Build</span></span></code></pre></div><p>来源：<a href="https://docs.coze.cn/what_is_coze" target="_blank" rel="noreferrer">what_is_coze</a>、<a href="https://docs.coze.cn/guides_welcome" target="_blank" rel="noreferrer">guides_welcome</a>、<a href="https://docs.coze.cn/about-low-code-project" target="_blank" rel="noreferrer">about-low-code-project</a>、<a href="https://docs.coze.cn/guides_FAQ" target="_blank" rel="noreferrer">guides_FAQ</a>、<a href="https://docs.coze.cn/cozespace_coze_app_faq" target="_blank" rel="noreferrer">cozespace_coze_app_faq</a>。</p><h2 id="目标与非目标" tabindex="-1">目标与非目标 <a class="header-anchor" href="#目标与非目标" aria-label="Permalink to &quot;目标与非目标&quot;">​</a></h2><p><strong>目标</strong></p><ul><li>分清扣子家族的门。</li><li>跟着官方步骤搭出一个低代码智能体并知道怎么发布。</li><li>需要工作流、知识库、插件、技能、CLI 时能跳到对应配方。</li></ul><p><strong>非目标</strong></p><ul><li>不写豆包、Trae、火山方舟的完整教程。</li><li>不写 PPT / 短视频 / 云手机的办公手册。</li><li>不解释模型内部机制（去 <a href="/zh/tech/fundamentals/LLM.html">Learn LLM</a>）。</li><li>不把开源 Studio 写成私有化实施全书。</li></ul><h2 id="该读哪一篇" tabindex="-1">该读哪一篇 <a class="header-anchor" href="#该读哪一篇" aria-label="Permalink to &quot;该读哪一篇&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>类型</th><th>什么时候看</th></tr></thead><tbody><tr><td><a href="./coze.html">上手教程</a></td><td>Tutorial</td><td>第一次：注册 → 低代码智能体 → 调试 → 发布</td></tr><tr><td><a href="./coze-cookbook.html">实战 Cookbook</a></td><td>How-to</td><td>已经会点界面，要解决一个具体问题</td></tr><tr><td><a href="./coze-cheatsheet.html">速查表</a></td><td>Reference</td><td>查套餐、渠道、CLI、限制、信息源</td></tr><tr><td><a href="./coze-glossary.html">术语表</a></td><td>Explanation</td><td>词撞车了，或旧教程里的 Bot / 豆包渠道对不上</td></tr></tbody></table><h2 id="学习路径" tabindex="-1">学习路径 <a class="header-anchor" href="#学习路径" aria-label="Permalink to &quot;学习路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>读什么</th><th>目标</th></tr></thead><tbody><tr><td>1. 分清门</td><td>本页决策树</td><td>不要进豆包或 Trae</td></tr><tr><td>2. 搭出一个智能体</td><td><a href="./coze.html">教程</a></td><td>走完官方「夸夸机器人」路径</td></tr><tr><td>3. 补能力</td><td><a href="./coze-cookbook.html">Cookbook</a></td><td>插件 / 知识库 / 工作流 / 发布 / CLI</td></tr><tr><td>4. 回查</td><td><a href="./coze-cheatsheet.html">速查表</a></td><td>套餐、渠道、命令</td></tr><tr><td>5. 对齐口径</td><td><a href="./coze-glossary.html">术语表</a></td><td>技能 vs 插件 vs 工作流</td></tr></tbody></table><h2 id="功能速查-扣子编程-·-搭建面" tabindex="-1">功能速查（扣子编程 · 搭建面） <a class="header-anchor" href="#功能速查-扣子编程-·-搭建面" aria-label="Permalink to &quot;功能速查（扣子编程 · 搭建面）&quot;">​</a></h2><p>只列官方有专题页的能力。</p><table tabindex="0"><thead><tr><th>能力</th><th>一句话</th><th>官方文档</th></tr></thead><tbody><tr><td>低代码智能体</td><td>人设 + 模型 + 技能面板，可视化编排</td><td><a href="https://docs.coze.cn/guides_agent_overview" target="_blank" rel="noreferrer">功能概述</a>、<a href="https://docs.coze.cn/guides_quickstart" target="_blank" rel="noreferrer">快速开始</a></td></tr><tr><td>全代码智能体</td><td>对话生成可部署的智能体项目</td><td><a href="https://docs.coze.cn/guides_vibe_coding_agent" target="_blank" rel="noreferrer">开发智能体</a></td></tr><tr><td>工作流 / 对话流</td><td>拖拽节点；对话流面向 Chatbot</td><td><a href="https://docs.coze.cn/guides_workflow" target="_blank" rel="noreferrer">低代码工作流</a></td></tr><tr><td>插件</td><td>一个插件里多个 API 工具</td><td><a href="https://docs.coze.cn/guides_plugin" target="_blank" rel="noreferrer">插件介绍</a></td></tr><tr><td>知识库</td><td>文档 / 表格 / 图片；另有火山知识库</td><td><a href="https://docs.coze.cn/guides_knowledge" target="_blank" rel="noreferrer">知识库概述</a></td></tr><tr><td>记忆</td><td>变量、数据库、长期记忆</td><td><a href="https://docs.coze.cn/guides_agent_overview" target="_blank" rel="noreferrer">功能概述 · 记忆</a></td></tr><tr><td>技能 Skill</td><td><code>SKILL.md</code> 文件夹，按需加载 SOP</td><td><a href="https://docs.coze.cn/guides_skill_overview" target="_blank" rel="noreferrer">技能概述</a></td></tr><tr><td>发布</td><td>商店、飞书、微信、小程序、API、Chat SDK</td><td><a href="https://docs.coze.cn/guides_publish_overview" target="_blank" rel="noreferrer">发布概览</a></td></tr><tr><td>Coze CLI</td><td><code>npm i -g @coze/cli</code>，命令名 <code>coze</code></td><td><a href="https://docs.coze.cn/developer_guides_coze_cli" target="_blank" rel="noreferrer">Coze CLI</a></td></tr></tbody></table><h2 id="时效性提醒" tabindex="-1">时效性提醒 <a class="header-anchor" href="#时效性提醒" aria-label="Permalink to &quot;时效性提醒&quot;">​</a></h2><ul><li><strong>扣子 3.0</strong>：官方写明 <strong>2026-05-29</strong> 发布多人多 Agent 协作（<a href="https://docs.coze.cn/cozespace_coze_app_faq" target="_blank" rel="noreferrer">消费端 FAQ</a>）。</li><li><strong>豆包发布渠道</strong>：低代码智能体入口 <strong>2026-07-01</strong> 下线。</li><li><strong>抖音分身</strong>：2025-09-03 下架。</li><li><strong>工作流 / 图像流商店</strong>：已下架，不能再往作品社区上架这两类资源。</li><li>旧博客里的「Bot + 一键发豆包 / Discord」不要当现行步骤。</li></ul><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./coze.html">上手教程</a></li><li><a href="./coze-cookbook.html">实战 Cookbook</a></li><li><a href="./coze-cheatsheet.html">速查表</a></li><li><a href="./coze-glossary.html">术语表</a></li><li><a href="./../">产品目录</a></li></ul>`,27)])])}const u=e(s,[["render",o]]);export{_ as __pageData,u as default};
